/// Look up a field's ApiFieldType by walking the type's inheritance chain.
pub fn lookup_api_field(st: StructType, field_name: &str) -> Option<ApiFieldType> {
    let mut current = st;
    loop {
        let info = &API_FIELD_TABLE[current as usize];
        for &(name, ft) in info.fields {
            if name == field_name {
                return Some(ft);
            }
        }
        current = match info.parent {
            Some(p) => p,
            None => return None,
        };
    }
}

#[inline]
pub fn resolve_type(type_name: &str) -> Option<StructType> {
    StructType::from_str(type_name)
}

/// XSD primitive local names (`string`, `int`, …) mapped to [`ApiFieldType`].
fn lookup_xml_primitive(type_name: &str) -> Option<ApiFieldType> {
    match type_name {
        "anyType" => Some(AFT_ANY),
        "base64Binary" => Some(AFT_BINARY),
        "boolean" => Some(AFT_BOOL),
        "byte" => Some(AFT_I_8),
        "dateTime" => Some(AFT_STR),
        "decimal" => Some(AFT_STR),
        "double" => Some(AFT_F_64),
        "float" => Some(AFT_F_32),
        "int" => Some(AFT_I_32),
        "long" => Some(AFT_I_64),
        "short" => Some(AFT_I_16),
        "string" => Some(AFT_STR),
        "unsignedByte" => Some(AFT_I_16),
        "unsignedInt" => Some(AFT_I_64),
        "unsignedLong" => Some(AFT_I_64),
        "unsignedShort" => Some(AFT_I_32),
        _ => None,
    }
}

