#[inline]
fn lookup_any_value_wrapper(type_name: &str) -> Option<ApiFieldType> {
    ANY_VALUE_WRAPPER_MAP.get(type_name).copied()
}

/// Resolve `xsi:type` local names (after stripping namespace prefixes) to an [`ApiFieldType`].
/// Resolution order: [`StructType`] first, then boxed `Any` value types (PHF), then XSD primitives.
pub fn lookup_xml_type(type_name: &str) -> Option<ApiFieldType> {
    resolve_type(type_name)
        .map(ApiFieldType::Object)
        .or_else(|| lookup_any_value_wrapper(type_name))
        .or_else(|| lookup_xml_primitive(type_name))
}
